def get_latest_source_version(self) -> str:
    """
    gets the version of the data

    :return:
    """
    import requests
    response = requests.get('https://yeastmine.yeastgenome.org/yeastmine/service/version/release')
    if response.status_code == 200:
        return response.json().get('release')
    else:
        return 'yeast_v1'
